// src/components/.../ProjectForm.js
// CHANGE: Simplified component per requirements — only the 7 specified fields,
// a "Bulk Upload Intakes" flow, and a data grid with an "Estimate Assigned to" dropdown.

import React, { useEffect, useMemo, useRef, useState } from "react";
import axios from "axios";
// CHANGE [CSS]: Use provided stylesheet for UI
//import "././styles/RecordEntry.css";
import "../../styles/RecordEntry.css";

import ""
// CHANGE [HELPER]: DB timestamp helper
function nowSQLite() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(
    d.getHours()
  )}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

// CHANGE [HELPER]: Small CSV parser that supports quoted fields + commas
function parseCSV(text) {
  const rows = [];
  let cur = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === `"`) {
        if (text[i + 1] === `"`) {
          field += `"`; // escaped quote
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
    } else {
      if (ch === `"`) {
        inQuotes = true;
      } else if (ch === ",") {
        cur.push(field);
        field = "";
      } else if (ch === "\n") {
        cur.push(field);
        field = "";
        if (cur.length > 1 || (cur.length === 1 && cur[0] !== "")) rows.push(cur);
        cur = [];
      } else if (ch === "\r") {
        // ignore \r (handle \r\n already)
      } else {
        field += ch;
      }
    }
  }
  if (field.length || cur.length) {
    cur.push(field);
    rows.push(cur);
  }
  return rows;
}

// CHANGE [HELPER]: Normalize header labels like "*Intake Number:" -> "intake number"
const normalizeHeader = (s) =>
  (s || "")
    .toString()
    .trim()
    .replace(/\*/g, "")
    .replace(/:/g, "")
    .toLowerCase();

// CHANGE [HEADERS]: Expected columns per requirements
const EXPECTED_HEADERS = [
  "intake number",   // "*Intake Number:"
  "intake name",     // "*Intake Name:"
  "qa assignee",     // "QA Assignee"
  "manager",         // "Manager"
  "pat assignee",    // "PAT Assignee"
  "status/eta",      // "Status/ETA"
];

// CHANGE [MAPPING]: Map UI/CSV -> DB columns for /api/projectmasterupdate
const CSV_TO_DB = {
  "intake number": { table: "projects", column: "intake_number" },
  "intake name":   { table: "projects", column: "intake_name"   },
  "qa assignee":   { table: "projects", column: "FuncSME"       },
  "manager":       { table: "projects", column: "QAManager"     },
  "pat assignee":  { table: "projects", column: "PATAssignee"   },
  "status/eta":    { table: "projects", column: "AutoEstimateDueDate" },
};

const ProjectForm = () => {
  // ======= Minimal single-entry fields (display only; not submitted) =======
  // CHANGE: Only keep these 7 fields on the page as requested
  const [form, setForm] = useState({
    intake_number: "",
    intake_name: "",
    qa_assignee: "",
    manager: "",
    automation_qe_lead: "",
    pat_assignee: "",
    status_eta: "",
  });

  // ======= Bulk upload state =======
  const [csvFile, setCsvFile] = useState(null);
  const [rows, setRows] = useState([]); // parsed + normalized CSV rows to display in grid
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");

  // ======= Resources for 'Estimate Assigned to' dropdown =======
  const [resources, setResources] = useState([]);
  useEffect(() => {
    // CHANGE [FETCH RESOURCES]: Populate dropdown from existing endpoint
    (async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/resourcefetch");
        const list =
          Array.isArray(res.data?.resources) ? res.data.resources :
          Array.isArray(res.data) ? res.data : [];
        setResources(list);
      } catch (e) {
        console.error("Failed to fetch resources", e);
      }
    })();
  }, []);

  // CHANGE [HANDLERS]: Field + CSV handlers
  const onChangeField = (e) => {
    const { name, value } = e.target;
    setForm((s) => ({ ...s, [name]: value }));
  };

  const onPickCSV = (e) => {
    setMessage("");
    const f = e.target?.files?.[0];
    setCsvFile(f || null);
  };

  const onParseCSV = async () => {
    setMessage("");
    if (!csvFile) return;

    const text = await csvFile.text();
    const raw = parseCSV(text);
    if (!raw.length) {
      setRows([]);
      setMessage("CSV appears empty.");
      return;
    }

    // header mapping
    const header = raw[0].map(normalizeHeader);
    const body = raw.slice(1);

    // Build index map with flexible match (e.g., include "status/eta")
    const idx = {};
    EXPECTED_HEADERS.forEach((key) => {
      const i = header.findIndex((h) => h === key);
      idx[key] = i >= 0 ? i : -1;
    });

    // Warn if any header missing
    const missing = Object.entries(idx)
      .filter(([_, i]) => i === -1)
      .map(([k]) => k);
    if (missing.length) {
      setMessage(`Missing expected columns in CSV: ${missing.join(", ")}`);
      // continue parsing the columns we have
    }

    const parsed = body
      .map((arr) => {
        const get = (key) => {
          const i = idx[key];
          return i >= 0 ? (arr[i] || "").trim() : "";
        };
        const record = {
          intake_number: get("intake number"),
          intake_name: get("intake name"),
          qa_assignee: get("qa assignee"),
          manager: get("manager"),
          pat_assignee: get("pat assignee"),
          status_eta: get("status/eta"),
          estimate_assigned_to: "", // dropdown selection (not in CSV)
        };
        // filter out empty lines
        const nonEmpty = Object.values(record).some((v) => String(v).length);
        return nonEmpty ? record : null;
      })
      .filter(Boolean);

    setRows(parsed);
    if (!parsed.length) setMessage("No valid data rows found in CSV.");
  };

  // CHANGE [UPLOAD]: Push each row into DB using /api/projectmasterupdate
  const onUpload = async () => {
    if (!rows.length) {
      setMessage("Nothing to upload. Please select and parse a CSV first.");
      return;
    }
    setUploading(true);
    setMessage("");

    try {
      for (const row of rows) {
        const updates = [];
        // map CSV fields to DB columns
        Object.entries(CSV_TO_DB).forEach(([key, cfg]) => {
          const v =
            key === "intake number" ? row.intake_number :
            key === "intake name"   ? row.intake_name :
            key === "qa assignee"   ? row.qa_assignee :
            key === "manager"       ? row.manager :
            key === "pat assignee"  ? row.pat_assignee :
            key === "status/eta"    ? row.status_eta : "";
          updates.push({ table: cfg.table, column: cfg.column, value: v });
        });
        // Also set AutoEstimateStatus = "Not Yet Assigned" per spec
        updates.push({ table: "projects", column: "AutoEstimateStatus", value: "Not Yet Assigned" });
        // Always stamp timestamp
        updates.push({ table: "projects", column: "timestamp", value: nowSQLite() });

        // POST once per intake (identified by intake_number)
        await axios.post("http://localhost:5000/api/projectmasterupdate", {
          intake_number: row.intake_number,
          updates,
        });
      }
      setMessage(`Uploaded ${rows.length} intake(s) successfully.`);
    } catch (e) {
      console.error("Bulk upload failed", e);
      setMessage("Upload failed. Check console/network logs.");
    } finally {
      setUploading(false);
    }
  };

  // ======= RENDER =======
  return (
    <div className="form-page">{/* from RecordEntry.css */}
      <h2>Project Form</h2>

      {/* CHANGE [ONLY FIELDS]: Keep ONLY the 7 fields below */}
      <div className="section">
        <div className="form-row">
          <div className="form-column">
            <label>*Intake Number:</label>
            <input
              type="text"
              name="intake_number"
              value={form.intake_number}
              onChange={onChangeField}
              placeholder="e.g. INTAKE-0001"
              required
            />
          </div>
          <div className="form-column">
            <label>*Intake Name:</label>
            <input
              type="text"
              name="intake_name"
              value={form.intake_name}
              onChange={onChangeField}
              placeholder="e.g. Payments Modernization"
              required
            />
          </div>
        </div>

        <div className="form-row">
          <div className="form-column">
            <label>QA Assignee</label>
            <input
              type="text"
              name="qa_assignee"
              value={form.qa_assignee}
              onChange={onChangeField}
              placeholder="Name"
            />
          </div>
          <div className="form-column">
            <label>Manager</label>
            <input
              type="text"
              name="manager"
              value={form.manager}
              onChange={onChangeField}
              placeholder="Name"
            />
          </div>
        </div>

        <div className="form-row">
          <div className="form-column">
            <label>*Automation QE Lead:</label>
            <input
              type="text"
              name="automation_qe_lead"
              value={form.automation_qe_lead}
              onChange={onChangeField}
              placeholder="Name"
              required
            />
          </div>
          <div className="form-column">
            <label>PAT Assignee</label>
            <input
              type="text"
              name="pat_assignee"
              value={form.pat_assignee}
              onChange={onChangeField}
              placeholder="Name"
            />
          </div>
        </div>

        <div className="form-row">
          <div className="form-column">
            <label>Status/ETA</label>
            <input
              type="text"
              name="status_eta"
              value={form.status_eta}
              onChange={onChangeField}
              placeholder="YYYY-MM-DD or text"
            />
          </div>
        </div>
      </div>

      {/* CHANGE [BULK UPLOAD]: Button + CSV chooser + Upload action */}
      <div className="section">
        <div className="form-row form-type-row" style={{ justifyContent: "space-between" }}>
          <button type="button" onClick={() => document.getElementById("csvPicker").click()}>
            Bulk Upload Intakes
          </button>
          <input
            id="csvPicker"
            type="file"
            accept=".csv,text/csv"
            style={{ display: "none" }}
            onChange={onPickCSV}
          />
          <div style={{ display: "flex", gap: 8 }}>
            <button type="button" onClick={onParseCSV} disabled={!csvFile}>
              Parse CSV
            </button>
            <button type="button" onClick={onUpload} disabled={!rows.length || uploading}>
              {uploading ? "Uploading..." : "Upload"}
            </button>
          </div>
        </div>

        {message && (
          <div className="error-message" style={{ color: message.includes("failed") ? "#c00" : "#064" }}>
            {message}
          </div>
        )}

        {/* CHANGE [GRID]: Show parsed/uploaded rows + 'Estimate Assigned to' dropdown */}
        <div className="section" style={{ overflowX: "auto" }}>
          <table className="min-w-full table-fixed" style={{ width: "100%" }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left", padding: 8 }}>*Intake Number:</th>
                <th style={{ textAlign: "left", padding: 8 }}>*Intake Name:</th>
                <th style={{ textAlign: "left", padding: 8 }}>QA Assignee</th>
                <th style={{ textAlign: "left", padding: 8 }}>Manager</th>
                <th style={{ textAlign: "left", padding: 8 }}>PAT Assignee</th>
                <th style={{ textAlign: "left", padding: 8 }}>Status/ETA</th>
                {/* CHANGE [NEW COL]: Estimate Assigned to (dropdown from resources) */}
                <th style={{ textAlign: "left", padding: 8 }}>Estimate Assigned to</th>
              </tr>
            </thead>
            <tbody>
              {rows.length ? (
                rows.map((r, i) => (
                  <tr key={`${r.intake_number}-${i}`}>
                    <td style={{ padding: 8 }}>
                      <input
                        type="text"
                        value={r.intake_number}
                        onChange={(e) =>
                          setRows((rs) =>
                            rs.map((x, ix) => (ix === i ? { ...x, intake_number: e.target.value } : x))
                          )
                        }
                      />
                    </td>
                    <td style={{ padding: 8 }}>
                      <input
                        type="text"
                        value={r.intake_name}
                        onChange={(e) =>
                          setRows((rs) =>
                            rs.map((x, ix) => (ix === i ? { ...x, intake_name: e.target.value } : x))
                          )
                        }
                      />
                    </td>
                    <td style={{ padding: 8 }}>
                      <input
                        type="text"
                        value={r.qa_assignee}
                        onChange={(e) =>
                          setRows((rs) =>
                            rs.map((x, ix) => (ix === i ? { ...x, qa_assignee: e.target.value } : x))
                          )
                        }
                      />
                    </td>
                    <td style={{ padding: 8 }}>
                      <input
                        type="text"
                        value={r.manager}
                        onChange={(e) =>
                          setRows((rs) =>
                            rs.map((x, ix) => (ix === i ? { ...x, manager: e.target.value } : x))
                          )
                        }
                      />
                    </td>
                    <td style={{ padding: 8 }}>
                      <input
                        type="text"
                        value={r.pat_assignee}
                        onChange={(e) =>
                          setRows((rs) =>
                            rs.map((x, ix) => (ix === i ? { ...x, pat_assignee: e.target.value } : x))
                          )
                        }
                      />
                    </td>
                    <td style={{ padding: 8 }}>
                      <input
                        type="text"
                        value={r.status_eta}
                        onChange={(e) =>
                          setRows((rs) =>
                            rs.map((x, ix) => (ix === i ? { ...x, status_eta: e.target.value } : x))
                          )
                        }
                      />
                    </td>
                    {/* NEW: Estimate Assigned to dropdown */}
                    <td style={{ padding: 8 }}>
                      <select
                        value={r.estimate_assigned_to || ""}
                        onChange={(e) =>
                          setRows((rs) =>
                            rs.map((x, ix) => (ix === i ? { ...x, estimate_assigned_to: e.target.value } : x))
                          )
                        }
                      >
                        <option value="">-- Select --</option>
                        {resources.map((name) => (
                          <option key={name} value={name}>
                            {name}
                          </option>
                        ))}
                      </select>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={7} style={{ padding: 12, color: "#555" }}>
                    No rows parsed yet. Choose a CSV and click <strong>Parse CSV</strong>.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default ProjectForm;
